<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $quote->reference }}</title><style>body{font:15px/1.5 Arial,sans-serif;color:#172033;max-width:900px;margin:40px auto;padding:20px}header{display:flex;justify-content:space-between;border-bottom:2px solid #334155;padding-bottom:18px}table{width:100%;border-collapse:collapse;margin-top:28px}th,td{padding:10px;border-bottom:1px solid #cbd5e1;text-align:left}.right{text-align:right}.total{font-size:20px;font-weight:bold}.muted{color:#64748b}@media print{.print{display:none}body{margin:0}}</style></head><body><button class="print" onclick="window.print()">Print / Save as PDF</button><header><div><h1>Quotation</h1><strong>{{ $quote->reference }} · Version {{ $quote->version }}</strong><p>{{ $quote->opportunity->name }}<br>{{ $quote->opportunity->account?->name }}<br>{{ $quote->opportunity->contact?->first_name }} {{ $quote->opportunity->contact?->last_name }}</p></div><div class="right"><strong>{{ $quote->currency }} {{ number_format((float)$quote->total,2) }}</strong><p class="muted">Valid until {{ $quote->valid_until?->format('d M Y') ?: 'Not specified' }}</p></div></header><table><thead><tr><th>Description</th><th>Pricing</th><th>Qty</th><th class="right">Unit price</th><th class="right">Line total</th></tr></thead><tbody>@foreach($quote->lines as $line)<tr><td>{{ $line->description }}</td><td>{{ ucfirst($line->pricing_type) }} {{ $line->billing_period }}</td><td>{{ $line->quantity }}</td><td class="right">{{ $quote->currency }} {{ number_format((float)$line->unit_price,2) }}</td><td class="right">{{ $quote->currency }} {{ number_format((float)$line->line_total,2) }}</td></tr>@endforeach</tbody><tfoot><tr><td colspan="4" class="right">Subtotal</td><td class="right">{{ $quote->currency }} {{ number_format((float)$quote->subtotal,2) }}</td></tr><tr><td colspan="4" class="right">Discount ({{ $quote->discount_percent }}%)</td><td class="right">{{ $quote->currency }} {{ number_format((float)$quote->subtotal*(float)$quote->discount_percent/100,2) }}</td></tr><tr><td colspan="4" class="right total">Total</td><td class="right total">{{ $quote->currency }} {{ number_format((float)$quote->total,2) }}</td></tr></tfoot></table>@if($quote->notes)<h3>Notes</h3><p style="white-space:pre-line">{{ $quote->notes }}</p>@endif</body></html>
